<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('billing.php');$page_title='Billing / Kasir';$page_subtitle=is_role('cashier')?'Revenue cycle: invoice dan penerimaan pembayaran.':'Tagihan pasien sendiri.';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'&&is_role('cashier')){check_csrf();$action=$_POST['action']??'';if($action==='invoice'){$pid=(int)$_POST['patient_id'];$desc=trim($_POST['description']);$qty=(int)$_POST['qty'];$price=(float)$_POST['price'];if(!$pid||$desc===''||$qty<1||$price<0)$msg='Data invoice tidak lengkap.';else{$pdo->beginTransaction();try{$no='INV-'.date('YmdHis').'-'.random_int(10,99);$q=$pdo->prepare("INSERT INTO invoices(patient_id,invoice_no,total,status) VALUES(?,?,?,'unpaid')");$q->execute([$pid,$no,$qty*$price]);$iid=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO invoice_items(invoice_id,description,qty,price) VALUES(?,?,?,?)');$q->execute([$iid,$desc,$qty,$price]);$pdo->commit();audit($pdo,'CREATE','BILLING',$iid,'Invoice dibuat oleh kasir.');$msg='Invoice '.$no.' berhasil dibuat.';}catch(Throwable $e){$pdo->rollBack();$msg='Invoice gagal dibuat.';}}}elseif($action==='pay'){$iid=(int)$_POST['invoice_id'];$amount=(float)$_POST['amount'];$method=$_POST['method']??'cash';$s=$pdo->prepare("SELECT total,COALESCE((SELECT SUM(amount) FROM payments WHERE invoice_id=i.id),0) paid FROM invoices i WHERE id=?");$s->execute([$iid]);$inv=$s->fetch();$remaining=$inv?(float)$inv['total']-(float)$inv['paid']:0;if(!$inv||$amount<=0||$amount>$remaining+0.001||!in_array($method,['cash','transfer','card','insurance'],true))$msg='Pembayaran tidak valid.';else{$q=$pdo->prepare('INSERT INTO payments(invoice_id,amount,method,received_by) VALUES(?,?,?,?)');$q->execute([$iid,$amount,$method,current_user_id()]);$st=$remaining-$amount<=.001?'paid':'partial';$pdo->prepare('UPDATE invoices SET status=? WHERE id=?')->execute([$st,$iid]);audit($pdo,'PAYMENT','BILLING',$iid,'Pembayaran dicatat oleh kasir.');$msg='Pembayaran berhasil dicatat.';}}}
$patients=is_role('cashier')?$pdo->query('SELECT id,mrn,name FROM patients ORDER BY name')->fetchAll():[];$where='';$params=[];if(is_role('patient')){$where='WHERE i.patient_id=?';$params=[current_patient_id($pdo)??0];}$sql="SELECT i.*,p.name patient,p.mrn,COALESCE((SELECT SUM(amount) FROM payments WHERE invoice_id=i.id),0) paid FROM invoices i JOIN patients p ON p.id=i.patient_id $where ORDER BY i.created_at DESC";$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();include __DIR__.'/includes/header.php';?><?php if($msg):?><div class="alert <?=str_contains($msg,'berhasil')?'success':'danger'?>"><?=h($msg)?></div><?php endif;?><?php if(is_role('cashier')):?><div class="card"><div class="card-header"><div><h3 class="section-title">Create Invoice</h3><p class="section-subtitle">Kasir membuat tagihan berdasarkan layanan yang perlu dibayar pasien.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="invoice"><div><label>Pasien</label><select name="patient_id" required><option value="">Pilih pasien</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=h($p['mrn'].' — '.$p['name'])?></option><?php endforeach;?></select></div><div><label>Deskripsi</label><input name="description" required placeholder="Konsultasi / tindakan / obat"></div><div><label>Qty</label><input type="number" name="qty" min="1" value="1" required></div><div><label>Harga Satuan</label><input type="number" name="price" min="0" required></div><div><button class="btn primary">+ Buat Invoice</button></div></form></div><div style="height:18px"></div><?php endif;?><div class="card"><div class="card-header"><div><h3 class="section-title"><?=is_role('patient')?'Tagihan Saya':'Billing Queue'?></h3><p class="section-subtitle"><?=count($rows)?> invoice tersedia.</p></div></div><div class="table-wrap"><table><tr><th>Invoice</th><th>Pasien</th><th>Total</th><th>Terbayar</th><th>Sisa</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $r):$remain=max(0,(float)$r['total']-(float)$r['paid']);?><tr><td><b><?=h($r['invoice_no'])?></b><br><span class="mini"><?=h(date('d/m/Y',strtotime($r['created_at'])))?></span></td><td><?=h($r['patient'])?></td><td>Rp <?=number_format($r['total'],0,',','.')?></td><td>Rp <?=number_format($r['paid'],0,',','.')?></td><td>Rp <?=number_format($remain,0,',','.')?></td><td><span class="badge <?=$r['status']==='paid'?'ok':($r['status']==='cancelled'?'danger':'warn')?>"><?=h(strtoupper($r['status']))?></span></td><td><?php if(is_role('cashier')&&$remain>0):?><form method="post" style="display:flex;gap:6px"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="pay"><input type="hidden" name="invoice_id" value="<?=$r['id']?>"><input type="number" name="amount" min="1" max="<?=h((string)$remain)?>" required placeholder="Nominal"><select name="method"><option>cash</option><option>transfer</option><option>card</option><option>insurance</option></select><button class="btn secondary">Bayar</button></form><?php else:?><span class="mini">Read-only</span><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php include __DIR__.'/includes/footer.php';?>